-- Seed the deterministic metric contract used by qilt-au-etl.
with defs(survey_code,code,name,category,unit,higher_is_better,description) as (values
('qilt_gos','fte','Full-time employment','employment','percent',true,'Published institution outcome; source confidence interval retained when available.'),('qilt_gos','oe','Overall employment','employment','percent',true,'Published institution outcome; source confidence interval retained when available.'),('qilt_gos','lf','Labour force participation rate','employment','percent',true,'Published institution outcome; source confidence interval retained when available.'),('qilt_gos','salary','Median annual full-time salaries','salary','AUD',true,'Published institution median salary in Australian dollars.'),
('qilt_ses','skills_development','Skills Development','experience','percent',true,'Published positive-rating indicator.'),('qilt_ses','peer_engagement','Peer Engagement','experience','percent',true,'Published positive-rating indicator.'),('qilt_ses','teaching_quality_engagement','Teaching Quality and Engagement','experience','percent',true,'Published positive-rating indicator.'),('qilt_ses','student_support_services','Student Support and Services','experience','percent',true,'Published positive-rating indicator.'),('qilt_ses','learning_resources','Learning Resources','experience','percent',true,'Published positive-rating indicator.'),('qilt_ses','overall_educational_experience','Quality of entire educational experience','experience','percent',true,'Published positive-rating indicator.'),
('qilt_gosl','medium_fte','Medium-term full-time employment','employment','percent',true,'Published medium-term domestic outcome from GOS-L.'),('qilt_gosl','medium_oe','Medium-term overall employment','employment','percent',true,'Published medium-term domestic outcome from GOS-L.'),('qilt_gosl','medium_salary','Medium-term median salary','salary','AUD',true,'Published medium-term domestic median salary from GOS-L.'),
('qilt_ess','foundation_skills','Foundation skills','employer_satisfaction','percent',true,'Published employer satisfaction with graduate foundation skills.'),('qilt_ess','adaptive_skills','Adaptive skills','employer_satisfaction','percent',true,'Published employer satisfaction with graduate adaptive skills.'),('qilt_ess','collaborative_skills','Collaborative skills','employer_satisfaction','percent',true,'Published employer satisfaction with graduate collaborative skills.'),('qilt_ess','technical_skills','Technical skills','employer_satisfaction','percent',true,'Published employer satisfaction with graduate technical skills.'),('qilt_ess','employability_skills','Employability skills','employer_satisfaction','percent',true,'Published employer satisfaction with graduate employability skills.'),('qilt_ess','overall_satisfaction','Overall satisfaction','employer_satisfaction','percent',true,'Published employer overall satisfaction.'))
insert into ref.outcome_metrics(survey_id,code,name,category,unit,higher_is_better,description,status) select s.id,d.code,d.name,d.category,d.unit,d.higher_is_better,d.description,'active' from defs d join ref.outcome_surveys s on s.code=d.survey_code on conflict(survey_id,code) do update set name=excluded.name,category=excluded.category,unit=excluded.unit,higher_is_better=excluded.higher_is_better,description=excluded.description,status='active',updated_at=now();
